insert into public.training_catalog(module_id,module_name,questions) values ('mod-y1-anat-general','Anatomie Générale & Ostéologie','[{"id":"q1","questionText":"Concernant l''ostéologie du membre supérieur, quelle affirmation est EXACTE ?","options":[{"id":"opt1","text":"La clavicule s''articule médialement avec l''acromion.","isCorrect":false},{"id":"opt2","text":"La gouttière bicipitale (sillon intertuberculaire) se situe à la face antérieure de l''humérus.","isCorrect":true},{"id":"opt3","text":"L''ulna s''articule directement avec le condyle carpien.","isCorrect":false},{"id":"opt4","text":"L''olécrane appartient à l''extrémité supérieure du radius.","isCorrect":false},{"id":"opt5","text":"Le scaphoïde est le plus médial des os de la première rangée du carpe.","isCorrect":false}],"explanation":"La gouttière bicipitale (ou sillon intertuberculaire) se situe bien entre le tubercule majeur et le tubercule mineur à la face antéro-supérieure de l''humérus. Elle livre passage au tendon du chef long du biceps brachial.","difficulty":"easy","source":"Faculté de Médecine - Examen Blanc 2023"},{"id":"q2","questionText":"Concernant l''articulation scapulo-humérale, quelles propositions sont vraies ?","options":[{"id":"opt21","text":"C''est une énarthrose (articulation sphéroïde) à 3 degrés de liberté.","isCorrect":true},{"id":"opt22","text":"Le bourrelet glénoïdien (labrum) diminue la congruence articulaire.","isCorrect":false},{"id":"opt23","text":"Le muscle supra-épineux est le principal initiateur de l''abduction.","isCorrect":true},{"id":"opt24","text":"Le nerf axillaire contourne le col chirurgical de l''humérus.","isCorrect":true},{"id":"opt25","text":"Le ligament coraco-huméral freine l''adduction.","isCorrect":false}],"explanation":"L''articulation gléno-humérale est une sphéroïde très mobile. Le bourrelet augmente la congruence (et non la diminue). Le nerf axillaire cravate le col chirurgical, ce qui l''expose aux fractures de cette région.","difficulty":"medium","source":"Concours de Médecine 2022"},{"id":"q3","questionText":"Parmi les muscles suivants, lequel est innervé par le nerf musculo-cutané ?","options":[{"id":"opt31","text":"Muscle triceps brachial","isCorrect":false},{"id":"opt32","text":"Muscle brachial antérieur (m. brachialis)","isCorrect":true},{"id":"opt33","text":"Muscle deltoïde","isCorrect":false},{"id":"opt34","text":"Muscle rond pronateur","isCorrect":false},{"id":"opt35","text":"Muscle subscapulaire","isCorrect":false}],"explanation":"Le nerf musculo-cutané innerve les trois muscles de la loge antérieure du bras : le coraco-brachial, le biceps brachial et le muscle brachial.","difficulty":"easy","source":"Anatomie - QCM Q/R"}]'::jsonb);
insert into public.training_catalog(module_id,module_name,questions) values ('mod-y2-cardio','Physiologie Cardiovasculaire','[{"id":"q2-1","questionText":"Concernant la contraction isovolumétrique ventriculaire, quelle affirmation est VRAIE ?","options":[{"id":"o1","text":"Elle débute à l''ouverture des valves sigmoïdes.","isCorrect":false},{"id":"o2","text":"Toutes les valves cardiaques sont fermées pendant cette phase.","isCorrect":true},{"id":"o3","text":"Le volume ventriculaire diminue rapidement.","isCorrect":false},{"id":"o4","text":"Elle correspond à l''onde T sur le tracé ECG.","isCorrect":false},{"id":"o5","text":"La pression ventriculaire reste inférieure à la pression atriale.","isCorrect":false}],"explanation":"Durant la phase de contraction isovolumétrique, les valves atrio-ventriculaires sont fermées (B1) et les valves sigmoïdes ne sont pas encore ouvertes. Le volume de sang intraventriculaire reste donc constant tandis que la pression grimpe en flèche.","difficulty":"medium","source":"Physiologie Médicale - Annales"}]'::jsonb);
insert into public.training_catalog(module_id,module_name,questions) values ('mod-y3-semio-cardio','Sémiologie Cardiovasculaire','[{"id":"q3-1","questionText":"Quel souffle cardiaque est typiquement un souffle méso-systolique éjectionnel irradiant aux carotides ?","options":[{"id":"os1","text":"Insuffisance mitrale","isCorrect":false},{"id":"os2","text":"Rétrécissement aortique (sténose aortique)","isCorrect":true},{"id":"os3","text":"Insuffisance aortique","isCorrect":false},{"id":"os4","text":"Rétrécissement mitral (roulement de Duroziez)","isCorrect":false},{"id":"os5","text":"Persistance du canal artériel","isCorrect":false}],"explanation":"Le souffle de rétrécissement aortique est typiquement rude, râpeux, méso-systolique (losangique), maximum au foyer aortique (2e EIC droit) et irradiant vers les vaisseaux du cou (carotides).","difficulty":"easy","source":"Sémiologie Clinique 2024"}]'::jsonb);
insert into public.training_catalog(module_id,module_name,questions) values ('mod-y4-cardio-sca','Syndromes Coronariens Aigus (SCA)','[{"id":"q4-1","questionText":"Chez un patient de 58 ans présentant une douleur rétrosternale constrictive depuis 45 min avec sus-décalage de ST en DII, DIII, aVF, quel traitement d''urgence est CONTRE-INDIQUÉ ?","options":[{"id":"ot1","text":"Aspirine par voie intraveineuse","isCorrect":false},{"id":"ot2","text":"Dérivés nitrés en cas d''extension au ventricule droit avec hypotension","isCorrect":true},{"id":"ot3","text":"Héparine non fractionnée ou HBPM","isCorrect":false},{"id":"ot4","text":"Inhibiteur de P2Y12 (Ticagrélor ou Prasugrel)","isCorrect":false},{"id":"ot5","text":"Angioplastie coronaire primaire en urgence","isCorrect":false}],"explanation":"En cas d''infarctus du myocarde inférieur avec extension au ventricule droit (V4R+), le débit cardiaque dépend strictement de la précharge ventriculaire droite. Les dérivés nitrés entraînent un effondrement de la précharge et une hypotension sévère réfractaire.","difficulty":"hard","source":"Cardiologie ECN / Résidanat","isClinicalCase":true}]'::jsonb);
